using System.Collections.Generic;
namespace RTMaquetaXR { internal static partial class ModLocalization {
static partial void AddRelease51(Dictionary<string,string> strings) {
Add(strings, "Native menus in every supported game screen.", "Menús originales en todas las pantallas compatibles.");
Add(strings, "Weapons inside; other abilities outside. No pages.", "Armas dentro; otras habilidades fuera. Sin páginas.");
Add(strings, "Click LEFT stick: Actions / Characters or Ships.", "Clic en stick IZQUIERDO: Acciones / Personajes o Naves.");
Add(strings, "Hold right grip and trigger for 0.15 s. Use the right stick for 1 s or point with the LEFT Touch and click its trigger. This is the native right options panel, including Space combat and navigation maps. Unavailable options are grey and cannot execute. B or releasing the opening controls closes it. No pages: all current options are on the wheel.", "Mantén grip y gatillo derechos 0,15 s. Mantén el stick derecho en una opción 1 s o señala con el Touch IZQUIERDO y pulsa su gatillo. Es el panel derecho original, también en Combate espacial y mapas. Las opciones no disponibles están grises y no se ejecutan. B o soltar la combinación lo cierra. Sin páginas: la rueda incluye todas las opciones actuales.");
Add(strings, "Hold left grip and trigger. Click LEFT stick to switch Actions / Characters, or Actions / Ships in Space combat. Active equipment appears in the centre. Weapons and weapon attacks are inside; other native abilities are outside. Move the stick farther for the outer ring, inward for the inner ring; a tolerance band prevents accidental switching. Preview with the stick or opposite Touch. A or RIGHT trigger uses the ability. Weapon changes refresh the whole wheel; centre the stick and release confirm before choosing again.", "Mantén grip y gatillo izquierdos. Pulsa el stick IZQUIERDO para alternar Acciones / Personajes, o Acciones / Naves en Combate espacial. El equipo activo aparece en el centro. Dentro están las armas y sus ataques; fuera, las otras habilidades originales. Lleva el stick más lejos para el aro exterior y hacia dentro para el interior; una franja de tolerancia evita cambios accidentales. Consulta con stick o Touch contrario. A o gatillo DERECHO ejecuta. Cambiar de arma actualiza toda la rueda; centra el stick y suelta la confirmación antes de elegir de nuevo.");
Add(strings, "Exploration actions need one selected character; otherwise the party wheel opens. In combat, actions and participants are independent. The stick or RIGHT trigger opens original actor information without selecting or moving the camera. Centring keeps it; another actor replaces it. Numbers show order and the halo marks the player turn. Additional participants use the second ring. B, releasing grip/trigger or changing wheel mode closes the information.", "En Exploración a pie, las acciones requieren un personaje seleccionado; en otro caso se abre el grupo. En combate, acciones y participantes son independientes. El stick o el gatillo DERECHO abre la información original sin seleccionar ni mover la cámara. Centrar mantiene la ficha; otro actor la sustituye. Los números indican el orden y el halo, el turno del jugador. Los participantes adicionales usan el segundo aro. B, soltar grip/gatillo o cambiar de modo cierra la información.");
Add(strings, "The same table gestures and LEFT-stick rotation/tilt apply, with ship-relative zoom. Battle entry frames our ship. Click orders without moving the camera; double-click frames the ship along its heading; full RIGHT trigger held for 2 s enters its view. LEFT wheel contains weapons, variants and ship-post abilities; click LEFT stick for the battle ships. RIGHT wheel contains native menus. A or the opposite trigger confirms abilities; end turn always asks for confirmation. Native rules, resources and cooldowns remain authoritative.", "Se mantienen los gestos de la maqueta y el giro/inclinación del stick IZQUIERDO, con zoom relativo a la nave. Al entrar se encuadra nuestra nave. Un clic da órdenes sin mover la cámara; el doble clic encuadra la nave siguiendo su dirección; mantener a fondo el gatillo DERECHO 2 s entra en su vista. La rueda IZQUIERDA contiene armas, variantes y habilidades de puestos; pulsa el stick IZQUIERDO para consultar las naves. La DERECHA contiene los menús originales. A o el gatillo contrario confirma habilidades; terminar turno siempre pide confirmación. Se respetan reglas, recursos y tiempos del juego.");
Add(strings, "INNER · WEAPONS    OUTER · ABILITIES", "DENTRO · ARMAS    FUERA · HABILIDADES");
Add(strings, "TWO RINGS · ALL OPTIONS", "DOS AROS · TODAS LAS OPCIONES");
Add(strings, "Ship actions / ships", "Acciones / naves");
Add(strings, "Right trigger · select / move", "Gatillo derecho · seleccionar / mover");
Add(strings, "Select / move", "Seleccionar / mover");
Add(strings, "Left wheel · ship actions / ships", "Rueda izquierda · acciones / naves");
Add(strings, "Full right trigger 2 s · first person", "Gatillo derecho a fondo 2 s · primera persona");
Add(strings, "Double right trigger · frame unit", "Doble gatillo derecho · encuadrar unidad");
Add(strings, "Right trigger drag · group selection", "Arrastrar con gatillo derecho · seleccionar grupo");
Add(strings, "Left stick click · map", "Clic en stick izquierdo · mapa");
Add(strings, "Right stick click held · highlight", "Mantener clic en stick derecho · resaltar");
Add(strings, "Full hold · first person", "A fondo · primera persona");
Add(strings, "Frame character / ship", "Encuadrar personaje / nave");
Add(strings, "Drag · select group", "Arrastrar · seleccionar grupo");
Add(strings, "Click left · map", "Clic izquierdo · mapa");
Add(strings, "Hold click · highlight", "Mantener clic · resaltar");
Add(strings, "Right stick · pan", "Stick derecho · desplazar");
